'use strict';

let state = null;
let cloudStatus = null;
let refreshInFlight = false;
const ui = {view:'overview',month:'',period:'month',currency:'CLP',person:'all',search:'',category:'all',kind:'all',transactionFilters:'',projectionYears:10,projectionRate:null,projectionMonthly:null,importPreview:null};
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n = v => Number(v) || 0;
const dateKey = v => String(v ?? '').slice(0,10);
const monthKey = v => dateKey(v).slice(0,7);
const monthLabel = (v,short=false) => new Date(`${v}-15T12:00:00`).toLocaleDateString('en-US',{month:short?'short':'long',year:short?undefined:'numeric'});
const dayLabel = v => new Date(`${dateKey(v)}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const pct = (v,d=0) => `${(n(v)*100).toFixed(d)}%`;
const personName = p => p==='neal' ? (state?.settings.neal_name || 'Neal') : p==='partner' ? (state?.settings.partner_name || 'Paola') : p==='family' ? 'Family' : 'Everyone';
const paths = {overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',transactions:'M4 6h16 M4 12h16 M4 18h16 M7 3v6 M17 9v6 M9 15v6',monthend:'M5 4h14v17H5z M8 2v4 M16 2v4 M8 10h8 M8 14h8 M8 18h4',investments:'M3 20h18 M5 16l5-5 4 2 6-9 M15 4h5v5',goals:'M21 12a9 9 0 1 1-9-9 M12 7a5 5 0 1 0 5 5 M12 12l8-8 M16 4h4v4',forecast:'M3 18l5-6 4 3 8-10 M15 5h5v5 M4 3v18h18',workbook:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h8 M11 10v9',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',down:'M12 4v16 M6 14l6 6 6-6',up:'M12 20V4 M6 10l6-6 6 6',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-1l2 6 M4 12l2 6a7 7 0 0 0 12-1',search:'M10.5 17a6.5 6.5 0 1 0 0-13 6.5 6.5 0 0 0 0 13 M16 16l5 5',close:'M6 6l12 12 M18 6 6 18',check:'M5 12l4 4L19 6',wallet:'M3 6h17v14H3z M3 6V4h14v2 M16 11h5v5h-5z',income:'M4 16l5-5 4 3 7-9 M15 5h5v5',expense:'M4 7l5 5 4-3 7 9 M15 18h5v-5',edit:'M4 16v4h4L20 8l-4-4z M14 6l4 4',lock:'M6 11h12v10H6z M8 11V7a4 4 0 0 1 8 0v4',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',chevron:'M9 5l7 7-7 7',settings:'M4 6h16 M4 12h16 M4 18h16 M9 3v6 M16 9v6 M10 15v6',home:'M3 11l9-8 9 8 M5 10v11h14V10 M9 21v-7h6v7',retirement:'M5 21V8h14v13 M3 8h18 M12 3l9 5 M12 3 3 8 M9 11v6 M15 11v6',info:'M12 11v6 M12 7v.1 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',archive:'M4 4h16v4H4z M6 8v13h12V8 M10 12h4',external:'M14 3h7v7 M10 14 21 3 M10 3H3v18h18v-7'};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.wallet}"/></svg>`;
const category = id => state.categories.find(c=>c.id===id) || {id,name:id || 'Uncategorized',color:'#96a98e',budget_clp:0};
const activeCategories = () => state.categories.filter(c=>!isTrue(c.archived));
const isTrue = v => v===true || String(v).toLowerCase()==='true' || v===1;
const selectedTransactions = (month=ui.month,person=ui.person) => state.transactions.filter(t=>monthKey(t.date)===month && (person==='all'||t.person===person));
const amountCLP = t => {
  if(t.charged_currency==='CLP')return n(t.charged_amount);
  return t.fx_clp_per_usd!==null&&t.fx_clp_per_usd!==''&&Number(t.fx_clp_per_usd)>0?n(t.charged_amount)*n(t.fx_clp_per_usd):null;
};
const fxFor = month => {
  const end=month+'-31';
  const quotes=(state.exchange_rates||[]).filter(r=>String(r.date).slice(0,10)<=end&&Number(r.clp_per_usd)>0).sort((a,b)=>String(a.date).localeCompare(String(b.date)));
  return quotes.length?Number(quotes[quotes.length-1].clp_per_usd):null;
};
const nativeCLP = (v,currency,month=ui.month) => n(v)*(currency==='USD'?fxFor(month):1);
const money = (v,opts={}) => {
  if(v===null||v===undefined||v==='')return 'Needs review';
  const currency=opts.currency || ui.currency;
  if(currency==='USD'&&!fxFor(opts.month||ui.month))return 'Rate unavailable';
  const val=currency==='USD'?n(v)/fxFor(opts.month||ui.month):n(v);
  return `${currency} ${new Intl.NumberFormat(currency==='CLP'?'es-CL':'en-US',{minimumFractionDigits:currency==='USD'&&!opts.whole?2:0,maximumFractionDigits:currency==='USD'&&!opts.whole?2:0}).format(val)}`;
};
const nativeMoney = (v,currency) => v===null||v===undefined||v===''?'Not supplied':`${currency} ${new Intl.NumberFormat(currency==='CLP'?'es-CL':'en-US',{maximumFractionDigits:currency==='USD'?2:0,minimumFractionDigits:currency==='USD'?2:0}).format(n(v))}`;
const compact = v => Math.abs(v)>=1e6?`${(v/1e6).toFixed(v%1e6===0?0:1)}m`:Math.abs(v)>=1e3?`${(v/1e3).toFixed(0)}k`:`${Math.round(v)}`;
const chartMoney = v => `${ui.currency==='USD'?'$':''}${compact(ui.currency==='USD'?v/fxFor(ui.month):v)}`;
const sum = (rows,fn) => rows.reduce((total,row)=>total+fn(row),0);
const roundCLP = value => Math.sign(value)*Math.floor(Math.abs(value)+0.5+1e-8);
const allMonths = () => [...new Set([...state.months,...state.transactions.map(t=>monthKey(t.date)),...state.settlements.map(t=>monthKey(t.date))])].filter(Boolean).sort();
const supportsAnnualReport = (view=ui.view) => ['overview','transactions'].includes(view);
const isYearReport = () => ui.period==='year'&&supportsAnnualReport();
const reportYear = () => ui.month.slice(0,4);
const inReport = date => isYearReport()?monthKey(date).slice(0,4)===reportYear():monthKey(date)===ui.month;
const reportLabel = () => isYearReport()?reportYear()+' · full year':monthLabel(ui.month);
const reportMonths = () => allMonths().filter(month=>month.slice(0,4)===reportYear());
function selectReportingYear(year){
  const months=allMonths().filter(month=>month.slice(0,4)===year);
  if(!months.length)return;
  const sameMonth=year+ui.month.slice(4);
  ui.month=months.includes(sameMonth)?sameMonth:months.at(-1);
  ui.projectionRate=null;ui.projectionMonthly=null;
}
function renderReportingControls(){
  if(!supportsAnnualReport())ui.period='month';
  const years=[...new Set(allMonths().map(month=>month.slice(0,4)))].sort().reverse();
  $('#year-select').innerHTML=years.map(year=>`<option value="${year}" ${reportYear()===year?'selected':''}>${year}</option>`).join('');
  $('#month-select').innerHTML=(supportsAnnualReport()?`<option value="year" ${isYearReport()?'selected':''}>Full year</option>`:'')+reportMonths().map(month=>`<option value="${month}" ${!isYearReport()&&ui.month===month?'selected':''}>${new Date(month+'-15T12:00:00').toLocaleDateString('en-US',{month:'long'})}</option>`).join('');
  const custom=ui.view==='transactions'&&window.CasaTransactionFilters?.hasDateRange(transactionSelection());
  $('#year-select').title=$('#month-select').title=custom?'Choose a year or month to leave the custom date range':'Reporting period';
}
const closedMonths = () => {const v=state.settings.closed_months; if(Array.isArray(v))return v;try{return JSON.parse(v||'[]')}catch{return []}};
const monthSummary = month => {
  const s=(state.monthly_summaries||[]).find(m=>m.month===month)||{};
  return {month,incomeNeal:s.income_neal_clp??null,incomePartner:s.income_partner_clp??null,income:s.income_clp??null,shared:s.shared_clp??null,paidNeal:s.shared_paid_neal_clp??null,paidPartner:s.shared_paid_partner_clp??null,ratio:s.neal_ratio??null,obligation:s.obligation_neal_clp??null,repaid:s.repaid_neal_clp||0,remaining:s.month_remaining_neal_clp??null,expenses:s.expense_clp??null,reasons:s.reasons||['Month requires review']};
};
const cumulative = month => {
  const s=(state.monthly_summaries||[]).find(m=>m.month===month);
  return {balance:s?.cumulative_neal_clp??null,unresolved:s?.cumulative_neal_clp===null||!s};
};
const direction = balance => Math.abs(balance)<1 ? 'All settled between you' : balance>0?`${personName('neal')} owes ${personName('partner')}`:`${personName('partner')} owes ${personName('neal')}`;
const selectedAccounts = () => state.investments.filter(a=>ui.person==='all'||a.person===ui.person);
const accountHistory = account => state.investment_history.filter(h=>h.account_id===account.id&&monthKey(h.date)<=ui.month).sort((a,b)=>dateKey(a.date).localeCompare(dateKey(b.date)));
const accountBalance = account => {const h=accountHistory(account);return h.length?n(h[h.length-1].balance):0;};
const portfolio = () => {
  const accounts=selectedAccounts();
  const balance=sum(accounts,a=>nativeCLP(accountBalance(a),a.currency));
  const contributed=sum(accounts,a=>nativeCLP(sum(accountHistory(a).slice(1),h=>n(h.contribution)),a.currency));
  const gain=sum(accounts,a=>nativeCLP(sum(accountHistory(a).slice(1),h=>n(h.net_gain)),a.currency));
  const monthly=sum(accounts,a=>nativeCLP(a.monthly_contribution,a.currency));
  const rate=balance?sum(accounts,a=>nativeCLP(accountBalance(a),a.currency)*(n(a.annual_return)-n(a.annual_fee)))/balance:0;
  return {accounts,balance,contributed,gain,monthly,rate};
};
const fv = (balance,monthly,rate,months) => {const r=Math.pow(1+Math.max(-.99,n(rate)),1/12)-1;return Math.abs(r)<1e-10?n(balance)+n(monthly)*months:n(balance)*Math.pow(1+r,months)+n(monthly)*(Math.pow(1+r,months)-1)/r;};
const addMonths = (month,offset) => {const d=new Date(`${month}-15T12:00:00`);d.setMonth(d.getMonth()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;};

async function request(path,body){
  const response=await fetch(path,{method:body?'POST':'GET',credentials:'omit',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});
  const result=await response.json();
  if(!response.ok){if(response.status===409&&body){try{await load(false)}catch{}}const error=new Error(result.error||'The workbook could not be updated.');error.status=response.status;throw error;}
  return result;
}
async function mutate(path,payload,success='Saved to Excel'){
  const result=await request(path,{version:state.version,...payload});
  acceptCloudResult(result,success);return state;
}
function googleMaster(){return state?.storage?.mode==='google';}
function normalizeSelectedMonth(){if(!ui.month)ui.month=state.settings.default_month||state.months.at(-1);if(!state.months.includes(ui.month)&&state.months.length)ui.month=state.months.at(-1);}
function acceptCloudResult(result,message){
  state=result.state||result;
  if(result.cloud_status)cloudStatus=result.cloud_status;
  else if(state.storage)cloudStatus={...(cloudStatus||{}),storage:state.storage};
  normalizeSelectedMonth();render();
  if(message)toast(googleMaster()?message.replace(/\bExcel\b/g,'Google Sheets'):message);
}
async function load(notify=false){
  if(notify&&refreshInFlight)return;
  const button=$('#refresh-button');
  if(notify){refreshInFlight=true;button.disabled=true;button.title='Refreshing master Sheet…';button.setAttribute?.('aria-busy','true');$('#save-status').textContent=googleMaster()?'Refreshing Google Sheet…':'Reloading workbook…';}
  try{
    const result=(!notify&&window.CasaWeb.takeInitialState?.())||await request(notify?'/api/refresh':'/api/state',notify?{}:undefined);
    state=result.state||result;
    if(result.cloud_status)cloudStatus=result.cloud_status;
    else{try{cloudStatus=await request('/api/cloud/status');}catch{cloudStatus=state.storage?{storage:state.storage}:null;}}
    normalizeSelectedMonth();$('#error-banner').hidden=true;render();
    if(notify)toast(googleMaster()?(state.storage.online?'Master Sheet refreshed':'Google unavailable · showing verified saved records'):'Workbook reloaded');
  }catch(error){if(notify)$('#save-status').textContent=googleMaster()?'Refresh failed · previous verified records':'Workbook reload failed';throw error;}
  finally{if(notify){refreshInFlight=false;button.disabled=false;button.setAttribute?.('aria-busy','false');button.title=googleMaster()?'Refresh master Sheet':'Reload workbook';}}
}
function showError(error){$('#error-banner').textContent=error.message||String(error);$('#error-banner').hidden=false;}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3400);}
function navigate(view){if(!views[view])return;ui.view=view;if(!supportsAnnualReport(view))ui.period='month';render();window.scrollTo(0,0);}
function personTabs(){return `<div class="person-tabs" role="group" aria-label="Filter by person">${['all','neal','partner'].map(p=>`<button class="person-tab ${ui.person===p?'active':''}" data-person="${p}" aria-pressed="${ui.person===p}">${esc(personName(p))}</button>`).join('')}</div>`;}
function pageHead(title,description,actions='',eyebrow='YOUR FAMILY, IN VIEW'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></div>`;}
function metric(label,value,note,iconName='wallet'){return `<div class="card metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(iconName)}</span></div><div class="metric-value amount-chip">${value}</div><div class="metric-note">${note}</div></div>`;}
function amountChip(value,compact=false){return `<span class="amount-chip${compact?' compact':''}">${esc(value)}</span>`;}
function categoryLabel(value){const c=typeof value==='string'?category(value):value;const v=window.CasaCategories?.visual(c)||{emoji:'🏷️',tone:'slate'};return `<span class="category-label"><span class="category-symbol" data-tone="${esc(v.tone)}" aria-hidden="true">${esc(v.emoji)}</span><span>${esc(c.name)}</span></span>`;}
function empty(title,description=''){return `<div class="empty-state"><strong>${title}</strong>${description}</div>`;}
function tooltipAttrs(text){return `data-tooltip="${esc(text)}" tabindex="0" aria-label="${esc(text)}"`;}

function lineChart(series,labels,{height=205,colors=['#388268','#9eb99a'],filled=false,clickMonths=null}={}){
  if(!labels.length)return empty('No history yet');
  const w=640,h=height,l=48,r=12,t=20,b=32,iw=w-l-r,ih=h-t-b;
  const values=series.flatMap(s=>s.values),min=Math.min(0,...values),max=Math.max(1,...values),span=max-min;
  const y=v=>t+ih-(v-min)/span*ih,x=i=>l+(labels.length===1?iw/2:i/(labels.length-1)*iw);
  let svg=`<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(series.map(s=>s.name).join(' and '))} over time">`;
  for(let i=0;i<4;i++){const v=min+span*i/3,yy=y(v);svg+=`<line class="chart-grid" x1="${l}" x2="${w-r}" y1="${yy}" y2="${yy}"/><text class="chart-label" x="${l-9}" y="${yy+3}" text-anchor="end">${esc(chartMoney(v))}</text>`;}
  labels.forEach((label,i)=>{if(labels.length<=12||i%Math.ceil(labels.length/10)===0||i===labels.length-1)svg+=`<text class="chart-label" x="${x(i)}" y="${h-9}" text-anchor="middle">${esc(label)}</text>`;});
  series.forEach((s,si)=>{
    const points=s.values.map((v,i)=>`${x(i)},${y(v)}`).join(' '),color=colors[si%colors.length];
    if(filled&&si===0)svg+=`<defs><linearGradient id="area-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".12"/><stop offset="100%" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="M${x(0)},${y(0)} L${points.replaceAll(' ', ' L')} L${x(labels.length-1)},${y(0)} Z" fill="url(#area-fill)"/>`;
    svg+=`<polyline points="${points}" fill="none" stroke="${color}" stroke-width="2.3" stroke-linejoin="round" stroke-linecap="round" ${si===1?'stroke-dasharray="4 5"':''}/>`;
    s.values.forEach((v,i)=>svg+=`<circle class="chart-point" cx="${x(i)}" cy="${y(v)}" r="3" fill="#fff" stroke="${color}" stroke-width="1.7" ${tooltipAttrs(`${labels[i]} · ${s.name}: ${money(v)}`)} ${clickMonths?`data-chart-month="${clickMonths[i]}"`:''}/>`);
  });
  return `<div class="chart-wrap">${svg}</svg><div class="chart-tooltip" hidden></div></div>`;
}
function cashBars(months){
  const values=months.map(monthSummary),w=640,h=207,l=45,r=12,t=15,b=32,iw=w-l-r,ih=h-t-b,max=Math.max(1,...values.flatMap(s=>[s.income,s.expenses]))*1.1,group=iw/months.length,bw=Math.min(19,group*.26);
  let svg=`<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Monthly income and expenses">`;
  for(let i=0;i<4;i++){const v=max*i/3,yy=t+ih-v/max*ih;svg+=`<line class="chart-grid" x1="${l}" x2="${w-r}" y1="${yy}" y2="${yy}"/><text class="chart-label" x="${l-8}" y="${yy+3}" text-anchor="end">${esc(chartMoney(v))}</text>`;}
  values.forEach((s,i)=>{const x=l+group*i+group/2;[['income','#56896b',-bw-2],['expenses','#c0d1b8',2]].forEach(([key,color,offset])=>{const val=s[key];svg+=`<rect class="chart-bar" x="${x+offset}" y="${t+ih-val/max*ih}" width="${bw}" height="${val/max*ih}" rx="3" fill="${color}" ${tooltipAttrs(`${monthLabel(s.month,true)} · ${key==='income'?'Income':'Expenses'}: ${money(val)}`)} data-chart-month="${s.month}"/>`;});svg+=`<text class="chart-label" x="${x}" y="${h-9}" text-anchor="middle">${monthLabel(s.month,true)}</text>`;});
  return `<div class="chart-wrap">${svg}</svg><div class="chart-tooltip" hidden></div></div>`;
}
function recentTable(rows,limit=4){return `<table class="compact-table"><thead><tr><th>Transaction</th><th>Person</th><th class="right">Amount</th></tr></thead><tbody>${rows.slice(0,limit).map(t=>`<tr><td><div class="transaction-name"><span class="merchant-badge">${esc(t.merchant.slice(0,1).toUpperCase())}</span><span><strong>${esc(t.merchant)}</strong><small>${esc(category(t.category_id).name)} · ${dayLabel(t.date)}</small></span></div></td><td><span class="pill ${t.person==='partner'?'purple':''}">${esc(personName(t.person))}</span></td><td class="right">${t.kind==='income'?'+':'−'}${money(amountCLP(t))}</td></tr>`).join('')}</tbody></table>`;}
function settlementHero(large=false){
  const s=monthSummary(ui.month),c=cumulative(ui.month);
  return `<div class="card settlement-hero ${large?'large':''}"><div class="hero-top"><h2 class="section-title">${large?'Your monthly balance':'Between the two of you'}</h2><span class="subtle-tag">${closedMonths().includes(ui.month)?'Month closed':'Month'}</span></div><div><div class="hero-caption">${s.remaining===null?'Confirmation needed':direction(s.remaining)}</div><div class="hero-value">${s.remaining===null?'Needs review':money(Math.abs(s.remaining))}</div><div class="hero-direction">${monthLabel(ui.month)} · after recorded repayments</div></div><div class="hero-bottom"><p>Cumulative through ${monthLabel(ui.month,true)}<br><strong>${c.unresolved?'Opening balance or prior months unresolved':`${direction(c.balance)} ${Math.abs(c.balance)<1?'':money(Math.abs(c.balance))}`}</strong></p><button class="button" data-action="${large?'repayment':'monthend'}">${large?'Record repayment':'See calculation'} ${icon('arrow')}</button></div></div>`;
}

function overviewPage(){
  const rows=selectedTransactions(),income=sum(rows.filter(t=>t.kind==='income'),amountCLP),expenses=sum(rows.filter(t=>t.kind==='expense'),amountCLP),p=portfolio(),surplus=income-expenses;
  const spendCategories=Object.values(rows.filter(t=>t.kind==='expense').reduce((acc,t)=>{acc[t.category_id]??={...category(t.category_id),total:0};acc[t.category_id].total+=amountCLP(t);return acc},{})).sort((a,b)=>b.total-a.total);
  const goals=state.goals.filter(g=>ui.person==='all'||g.person===ui.person||g.person==='family').slice(0,3);
  return `${pageHead('Your family finances',`Here’s ${ui.person==='all'?'your household':esc(personName(ui.person))} in ${monthLabel(ui.month)}.`,`<button class="button" data-action="import">${icon('upload')} Import CSV</button><button class="button primary" data-action="new-transaction">${icon('plus')} Add transaction</button>`)}${personTabs()}<div class="metrics-grid">${metric('Income recorded',money(income),'Received this month', 'income')}${metric('Total expenses',money(expenses),'Shared and personal spending','expense')}${metric('Income less expenses',money(surplus),`${income>0?pct(surplus/income):'—'} of income · before investments`,'wallet')}${metric('Invested balance',money(p.balance),`Valued at ${monthLabel(ui.month)} · ${p.accounts.length} accounts`,'investments')}</div><div class="overview-first">${practicalSettlementHero()}<div class="card savings-card"><div class="savings-top"><div><h2 class="section-title">Where your income went</h2><div class="savings-rate"><strong>${income>0?pct(Math.max(0,surplus)/income):'—'}</strong><span>left after expenses</span></div></div><span class="metric-icon">${icon('wallet')}</span></div><div class="savings-bars"><span style="background:#679273;flex:${Math.max(0,expenses)}"></span><span style="background:#cad9bb;flex:${Math.max(0,surplus)}"></span></div><div class="mini-legend"><span class="legend-item"><i class="legend-dot" style="background:#679273"></i>Expenses ${money(expenses)}</span><span class="legend-item"><i class="legend-dot" style="background:#cad9bb"></i>Remaining ${money(surplus)}</span></div><p class="savings-note">Investment contributions and savings allocations come from the remaining amount.</p></div></div><div class="section-grid"><div class="card chart-card"><div class="card-header"><div><h2 class="section-title">The monthly picture</h2><p>Household income and expenses · ${ui.currency}</p></div><div class="chart-legend"><span class="legend-item"><i class="legend-dot" style="background:#56896b"></i>Income</span><span class="legend-item"><i class="legend-dot" style="background:#c0d1b8"></i>Expenses</span></div></div>${cashBars(allMonths().filter(m=>m<=ui.month).slice(-7))}<p class="table-note">Click a month to explore its transactions. Household totals include both people.</p></div><div class="card card-pad"><div class="card-header"><div><h2 class="section-title">Spending by category</h2><p>${ui.person==='all'?'Everyone':esc(personName(ui.person))} · this month</p></div><button class="small-link" data-action="categories">Manage ${icon('chevron')}</button></div><div class="category-list">${spendCategories.slice(0,5).map(c=>`<div class="category-row" role="button" tabindex="0" data-drill-category="${esc(c.id)}"><div class="category-icon" style="color:${esc(c.color)};background:${esc(c.color)}15">${icon(c.name.toLowerCase().includes('hous')?'home':'wallet')}</div><div><div class="category-name">${esc(c.name)}</div><div class="category-track"><div class="category-fill" style="width:${expenses?c.total/expenses*100:0}%;background:${esc(c.color)}"></div></div></div><div class="category-value">${money(c.total)}<small>${expenses?pct(c.total/expenses):'0%'} of spending</small></div></div>`).join('')||empty('No spending this month')}</div></div></div><div class="bottom-grid"><div class="card card-pad"><div class="card-header"><h2 class="section-title">Recent activity</h2><button class="small-link" data-action="transactions">All transactions ${icon('chevron')}</button></div>${recentTable([...rows].sort((a,b)=>dateKey(b.date).localeCompare(dateKey(a.date))))}</div><div class="card card-pad"><div class="card-header"><h2 class="section-title">The things you’re working toward</h2><button class="small-link" data-action="goals">All goals ${icon('chevron')}</button></div>${goals.map(g=>`<div class="goal-mini"><div class="goal-mini-top"><span>${esc(g.name)}</span><small>${pct(n(g.saved)/n(g.target))}</small></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,n(g.saved)/n(g.target)*100)}%"></div></div><div class="goal-mini-bottom"><span>${nativeMoney(g.saved,g.currency)} saved</span><span>of ${nativeMoney(g.target,g.currency)}</span></div></div>`).join('')||empty('No goals yet','Add something you want to work toward.')}</div></div>`;
}

function filteredTransactions(){return selectedTransactions().filter(t=>(ui.category==='all'||t.category_id===ui.category)&&(ui.kind==='all'||t.kind===ui.kind)&&`${t.merchant} ${t.notes||''} ${t.order_details||''} ${JSON.stringify(state.source_evidence?.[t.id]||[])} ${category(t.category_id).name}`.toLowerCase().includes(ui.search.toLowerCase())).sort((a,b)=>dateKey(b.date).localeCompare(dateKey(a.date)));}
function transactionPage(){
  const rows=filteredTransactions();
  return `${pageHead('Every transaction, in one place.',`Explore ${monthLabel(ui.month)}. Click a row to edit its details.`,`<button class="button" data-action="categories">${icon('settings')} Categories</button><button class="button" data-action="import">${icon('upload')} Import CSV</button><button class="button primary" data-action="new-transaction">${icon('plus')} Add transaction</button>`)}${personTabs()}<div class="toolbar"><div class="search-field">${icon('search')}<label class="sr-only" for="transaction-search">Search transactions</label><input id="transaction-search" placeholder="Search transactions…" value="${esc(ui.search)}"></div><label class="sr-only" for="category-filter">Category</label><select id="category-filter"><option value="all">All categories</option>${state.categories.map(c=>`<option value="${esc(c.id)}" ${ui.category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label class="sr-only" for="kind-filter">Transaction type</label><select id="kind-filter"><option value="all">Income & expenses</option><option value="expense" ${ui.kind==='expense'?'selected':''}>Expenses</option><option value="income" ${ui.kind==='income'?'selected':''}>Income</option></select></div><div class="card table-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Transaction</th><th>Person</th><th>Category</th><th>Household use</th><th class="right">Amount</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr data-edit="${esc(t.id)}" tabindex="0" aria-label="Edit ${esc(t.merchant)}"><td>${dayLabel(t.date)}</td><td><div class="transaction-name"><span class="merchant-badge">${esc(t.merchant.slice(0,1))}</span><span><strong>${esc(t.merchant)}</strong><small>${nativeMoney(t.charged_amount,t.charged_currency)} charged${t.currency!==t.charged_currency?` · purchased in ${esc(t.currency)}`:''}</small></span></div></td><td>${esc(personName(t.person))}</td><td><span class="pill neutral">${esc(category(t.category_id).name)}</span></td><td><span class="pill ${t.sharing==='shared'?'':'neutral'}">${t.kind==='income'?'Income':t.sharing==='shared'?'Shared':'Personal'}</span></td><td class="right ${t.kind==='income'?'stat-positive':''}">${t.kind==='income'?'+':'−'}${money(amountCLP(t))}</td><td><span class="muted">${icon('chevron')}</span></td></tr>`).join('')}</tbody></table>${rows.length?'':empty('No transactions match','Try another category, person, or month.')}</div><div class="table-footer"><span>${rows.length} transactions · ${closedMonths().includes(ui.month)?'Month closed · reopen to edit':'Changes save directly to Excel'}</span><span>Expenses ${money(sum(rows.filter(t=>t.kind==='expense'),amountCLP))}</span></div></div><p class="table-note">Original and bank-charged amounts are preserved. Exchange rates are saved with each transaction. Repayments between you appear in Month.</p>`;
}

function monthEndPage(){
  const s=monthSummary(ui.month),c=cumulative(ui.month),closed=closedMonths().includes(ui.month),repayments=state.settlements.filter(t=>monthKey(t.date)===ui.month);
  return `${pageHead('One month. One clear balance.',`The household calculation for ${monthLabel(ui.month)} includes both of you.`,`<button class="button" data-action="${closed?'reopen-month':'close-month'}">${icon(closed?'edit':'lock')} ${closed?'Reopen month':'Close month'}</button><button class="button primary" data-action="repayment">${icon('plus')} Record repayment</button>`,'BETWEEN THE TWO OF YOU')}<div class="overview-first">${practicalSettlementHero(true)}<div class="card card-pad"><div class="card-header"><div><h2 class="section-title">Your income shares</h2><p>Based on income actually received this month</p></div></div><div class="person-share"><div class="person-share-header"><span>${esc(personName('neal'))} · ${money(s.incomeNeal)}</span><strong>${s.ratio===null?'—':pct(s.ratio,1)}</strong></div><div class="progress-track"><div class="progress-fill" style="width:${n(s.ratio)*100}%;background:#6b9573"></div></div></div><div class="person-share"><div class="person-share-header"><span>${esc(personName('partner'))} · ${money(s.incomePartner)}</span><strong>${s.ratio===null?'—':pct(1-s.ratio,1)}</strong></div><div class="progress-track"><div class="progress-fill" style="width:${s.ratio===null?0:(1-s.ratio)*100}%;background:#b4b095"></div></div></div><p class="large-note">Personal spending is excluded. Shared purchases are pooled before calculating the amount due.</p></div></div>${s.ratio===null?`<div class="notice amber">Add received income for this month before calculating proportional sharing. No sharing ratio has been assumed.</div>`:''}<div class="section-grid"><div class="card card-pad"><div class="card-header"><h2 class="section-title">How this month adds up</h2><span class="pill">${ui.currency}</span></div><div class="explain-row"><span>Total shared household expenses</span><strong>${money(s.shared)}</strong></div><div class="explain-row"><span>${esc(personName('neal'))}’s responsibility ${s.ratio===null?'':`(${pct(s.ratio,1)})`}</span><strong>${s.ratio===null?'—':money(s.shared*s.ratio)}</strong></div><div class="explain-row"><span>Less shared expenses ${esc(personName('neal'))} paid</span><strong>−${money(s.paidNeal)}</strong></div><div class="explain-row"><span>Net repayments ${esc(personName('neal'))} sent this month</span><strong>${s.repaid<0?'+':'−'}${money(Math.abs(s.repaid))}</strong></div><div class="explain-row total"><span>${s.remaining===null?'Income needed':direction(s.remaining)}</span><strong>${s.remaining===null?'—':money(Math.abs(s.remaining))}</strong></div><p class="table-note">The calculation is performed in CLP and rounded to the nearest peso. The USD view uses this month’s saved reporting rate.</p></div><div class="card card-pad"><div class="card-header"><h2 class="section-title">Repayments this month</h2><button class="small-link" data-action="repayment">Add ${icon('plus')}</button></div>${repayments.length?repayments.map(r=>`<div class="explain-row"><span>${esc(personName(r.from_person))} → ${esc(personName(r.to_person))}<br><small class="muted">${dayLabel(r.date)}${r.notes?` · ${esc(r.notes)}`:''}</small></span><strong>${money(r.amount_clp)}</strong></div>`).join(''):empty('No repayments recorded','Record a transfer when it has actually happened.')}<div class="notice" style="margin-top:17px">Repayments reduce the balance between you. They do not create household income or expenses.</div></div></div><div class="card card-pad subsection"><div class="card-header"><div><h2 class="section-title">The balance over time</h2><p>All earlier months carry forward · click a month to review it</p></div><span class="pill ${c.unresolved?'amber':''}">${c.unresolved?'Missing income to resolve':'Opening balance: CLP 0'}</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Month</th><th class="right">Shared expenses</th><th class="right">Monthly obligation¹</th><th class="right">Net repayments¹</th><th class="right">Running balance¹</th><th>Status</th></tr></thead><tbody>${allMonths().filter(m=>m<=ui.month).map(m=>{const ms=monthSummary(m),cum=cumulative(m);return `<tr class="month-history-row ${m===ui.month?'selected-row':''}" data-select-month="${m}" tabindex="0"><td>${monthLabel(m)}</td><td class="right">${money(ms.shared)}</td><td class="right">${ms.obligation===null?'Unresolved':money(ms.obligation)}</td><td class="right">${money(ms.repaid)}</td><td class="right">${cum.unresolved?'Unresolved':money(cum.balance)}</td><td><span class="pill ${closedMonths().includes(m)?'neutral':''}">${closedMonths().includes(m)?'Closed':'Open'}</span></td></tr>`}).join('')}</tbody></table></div><p class="table-note">¹ Positive obligation or running balance means ${esc(personName('neal'))} owes ${esc(personName('partner'))}; negative means the reverse. Positive net repayments mean ${esc(personName('neal'))} paid ${esc(personName('partner'))}.</p></div>`;
}

function portfolioChart(){
  const accounts=selectedAccounts(),months=[...new Set(state.investment_history.map(h=>monthKey(h.date)))].sort().filter(m=>m<=ui.month);
  const balances=months.map(m=>sum(accounts,a=>{const history=state.investment_history.filter(h=>h.account_id===a.id&&monthKey(h.date)<=m).sort((x,y)=>dateKey(x.date).localeCompare(dateKey(y.date)));return nativeCLP(history.at(-1)?.balance||0,a.currency)}));
  return lineChart([{name:'Portfolio balance',values:balances}],months.map(m=>monthLabel(m,true)),{filled:true,height:215});
}
function investmentInsights(){
  const p=portfolio(),insights=[];
  const concentrated=p.accounts.filter(a=>n(a.single_asset_fraction)>.2).sort((a,b)=>n(b.single_asset_fraction)-n(a.single_asset_fraction))[0];
  if(concentrated)insights.push({tag:'Concentration',title:`Review ${personName(concentrated.person)}’s largest holding`,text:`${pct(concentrated.single_asset_fraction)} of ${concentrated.name} is in one asset in this sample. Ask your wealth manager how this affects your total household exposure.`,url:'https://www.investor.gov/introduction-investing/getting-started/asset-allocation',link:'About diversification'});
  const costly=p.accounts.filter(a=>n(a.annual_fee)>.01).sort((a,b)=>n(b.annual_fee)-n(a.annual_fee))[0];
  if(costly)insights.push({tag:'Ongoing costs',title:`Make the ${pct(costly.annual_fee,1)} annual fee visible`,text:`${costly.name} has the highest sample fee. Compare the service, fund costs, and any exit costs before considering a change. Small recurring fees compound over time.`,url:'https://www.investor.gov/introduction-investing/getting-started/understanding-fees',link:'How investment fees work'});
  const nearGoal=state.goals.filter(g=>(ui.person==='all'||g.person===ui.person||g.person==='family')&&dateKey(g.target_date)<=`${addMonths(ui.month,36)}-31`&&n(g.saved)<n(g.target))[0];
  if(nearGoal)insights.push({tag:'Time horizon',title:`Check the plan for ${nearGoal.name.toLowerCase()}`,text:`This goal is due ${new Date(`${dateKey(nearGoal.target_date)}T12:00:00`).toLocaleDateString('en-US',{month:'short',year:'numeric'})}. Discuss whether the investments supporting it match the time available and your tolerance for a loss before then.`,url:'https://www.investor.gov/introduction-investing/investing-basics/invest-your-goals',link:'Investing around your goals'});
  if(!insights.length)insights.push({tag:'Portfolio review',title:'Connect the investments to your plans',text:'Review allocation, fees, upcoming spending, and contribution affordability together with your wealth manager. Your sample data does not trigger the demo concentration or fee prompts.',url:'https://www.investor.gov/introduction-investing/investing-basics/invest-your-goals',link:'Investing around your goals'});
  return insights.map(i=>`<article class="insight-card"><div class="insight-symbol">${esc(i.tag)}</div><h3>${esc(i.title)}</h3><p>${esc(i.text)}</p><a href="${i.url}" target="_blank" rel="noopener">${esc(i.link)} ↗</a></article>`).join('');
}
function investmentPage(){
  const p=portfolio();if(ui.projectionRate===null)ui.projectionRate=p.rate*100;if(ui.projectionMonthly===null)ui.projectionMonthly=p.monthly;
  return `${pageHead('Your future has a place here.',`Brokerage, retirement, and life-goal accounts · values as of ${monthLabel(ui.month)}.`,`<button class="button primary" data-action="new-investment">${icon('plus')} Add account</button>`,'INVESTMENTS & RETIREMENT')}${personTabs()}<div class="metrics-grid">${metric('Total invested',money(p.balance),`${p.accounts.length} accounts · goals are not added again`,'investments')}${metric('Added since first snapshot',money(p.contributed),'Contributions after the starting snapshot','income')}${metric('Investment gains',money(p.gain),'Since first snapshot · before FX movements','forecast')}${metric('Planned monthly contributions',money(p.monthly),'Editable account assumptions','wallet')}</div><div class="section-grid"><div class="card chart-card"><div class="card-header"><div><h2 class="section-title">Progress, over time</h2><p>Historical balance · ${ui.person==='all'?'Everyone':esc(personName(ui.person))}</p></div><span class="pill">${ui.currency}</span></div>${portfolioChart()}<p class="table-note">History uses ${monthLabel(ui.month)}’s reporting rate throughout, separating market progress from exchange-rate changes. All values are invented.</p></div><div class="card card-pad"><div class="card-header"><h2 class="section-title">Where the money is invested</h2></div>${['Brokerage','Retirement','Life goal'].map((type,i)=>{const balance=sum(p.accounts.filter(a=>a.type===type),a=>nativeCLP(accountBalance(a),a.currency));return `<div class="allocation-row"><span><i class="legend-dot" style="background:${['#65906d','#a8b692','#c1b59c'][i]};margin-right:7px"></i>${type}</span><strong>${money(balance)}</strong></div>`}).join('')}<div class="notice" style="margin-top:20px">Life goals can reference these accounts. Goal allocations are included in account balances, so they are never counted twice.</div></div></div><div class="account-grid">${p.accounts.map(a=>`<article class="card account-card"><div class="account-card-top"><span class="account-avatar">${icon(a.type==='Retirement'?'retirement':a.type==='Life goal'?'goals':'investments')}</span><button class="icon-button" data-edit-investment="${esc(a.id)}" aria-label="Edit ${esc(a.name)}">${icon('edit')}</button></div><h3>${esc(a.name)}</h3><div class="account-owner">${esc(personName(a.person))} · ${esc(a.type)}</div><div class="account-balance">${money(nativeCLP(accountBalance(a),a.currency))}</div><div class="account-native">${nativeMoney(accountBalance(a),a.currency)} in account currency</div><div class="account-footer"><span>${nativeMoney(a.monthly_contribution,a.currency)} / month planned</span><span>${pct(n(a.annual_return)-n(a.annual_fee),1)} assumed net return</span></div></article>`).join('')}</div><div class="card card-pad subsection"><div class="card-header"><div><h2 class="section-title">What could consistent investing look like?</h2><p>Explore an assumption · this does not change historical balances</p></div></div><div class="projection-controls"><div class="field"><label for="projection-years">Time horizon: <strong id="projection-years-label">${ui.projectionYears} years</strong></label><input id="projection-years" type="range" min="1" max="35" step="1" value="${ui.projectionYears}"></div><div class="field"><label for="projection-rate">Annual return after fees (%)</label><input id="projection-rate" type="number" min="-50" max="30" step="0.1" value="${n(ui.projectionRate).toFixed(1)}"></div><div class="field"><label for="projection-monthly">Monthly contribution (${ui.currency})</label><input id="projection-monthly" type="number" min="0" step="${ui.currency==='CLP'?1:0.01}" value="${Math.round(ui.currency==='USD'?ui.projectionMonthly/fxFor(ui.month):ui.projectionMonthly)}"></div></div><div id="projection-output">${projectionOutput()}</div><p class="table-note">Illustrative nominal returns after assumed fees, before taxes and inflation. Monthly contributions occur at month end. The assumed return stays constant. Market volatility is not modeled. Changing these controls does not save account assumptions.</p></div><div class="subsection"><div class="card-header"><div><h2 class="section-title">Ideas to bring to your wealth manager</h2><p>Triggered by this demo’s figures · thresholds are illustrative review rules</p></div></div><div class="insights-grid">${investmentInsights()}</div></div>`;
}
function projectionOutput(){
  const p=portfolio(),rate=n(ui.projectionRate)/100,monthly=n(ui.projectionMonthly),years=n(ui.projectionYears),future=fv(p.balance,monthly,rate,years*12),contributions=p.balance+monthly*years*12;
  const steps=Array.from({length:years+1},(_,i)=>i),labels=steps.map(y=>y===0?'Now':`${y}y`);
  return `<div class="projection-result">${money(future)} <small>projected after ${years} years</small></div>${lineChart([{name:'Projected balance',values:steps.map(y=>fv(p.balance,monthly,rate,y*12))},{name:'Starting balance + new contributions',values:steps.map(y=>p.balance+monthly*y*12)}],labels,{height:190,filled:true})}<div class="chart-legend"><span class="legend-item"><i class="legend-dot" style="background:#388268"></i>Projected balance</span><span class="legend-item"><i class="legend-dot" style="background:#9eb99a"></i>Starting balance + contributions ${money(contributions)}</span></div>`;
}

function goalsPage(){
  const goals=state.goals.filter(g=>ui.person==='all'||g.person===ui.person||g.person==='family');
  return `${pageHead('Give your money a direction.',`Life plans and retirement milestones, with a clear path toward each.`,`<button class="button primary" data-action="new-goal">${icon('plus')} Add goal</button>`,'LIFE GOALS')}${personTabs()}<div class="notice" style="margin-bottom:21px">Goal savings are allocations of existing investment accounts. They are shown for planning and are not added to your invested balance again.</div><div class="goal-grid">${goals.map(g=>{const months=Math.max(0,(new Date(`${dateKey(g.target_date)}T12:00:00`).getFullYear()-Number(ui.month.slice(0,4)))*12+new Date(`${dateKey(g.target_date)}T12:00:00`).getMonth()-(Number(ui.month.slice(5,7))-1));const projected=fv(g.saved,g.monthly_contribution,g.annual_return,months);const ratio=n(g.target)>0?n(g.saved)/n(g.target):0;return `<article class="card goal-card"><div class="goal-card-top"><div><div class="eyebrow">${esc(personName(g.person))}</div><h3>${esc(g.name)}</h3><p>Target ${new Date(`${dateKey(g.target_date)}T12:00:00`).toLocaleDateString('en-US',{month:'long',year:'numeric'})}</p></div><button class="icon-button" data-edit-goal="${esc(g.id)}" aria-label="Edit ${esc(g.name)}">${icon('edit')}</button></div><div class="goal-card-value">${nativeMoney(g.saved,g.currency)} <small>of ${nativeMoney(g.target,g.currency)}</small></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,ratio*100)}%;background:${g.person==='partner'?'#b0a6c0':g.person==='family'?'#bba882':'#7c9d6b'}"></div></div><div class="goal-metadata"><div><span>Progress</span><strong>${pct(ratio,1)}</strong></div><div><span>Monthly contribution</span><strong>${nativeMoney(g.monthly_contribution,g.currency)}</strong></div><div><span>Assumed annual return</span><strong>${pct(g.annual_return,1)} after fees</strong></div></div><div class="notice ${projected<n(g.target)?'amber':''}" style="margin-top:22px">${projected>=n(g.target)?'At these assumptions, projected savings reach the target.':`At these assumptions, the projected gap is ${nativeMoney(n(g.target)-projected,g.currency)}.`} Projected value: ${nativeMoney(projected,g.currency)}.</div></article>`}).join('')||empty('Make room for your first goal','Add a target, a date, and a monthly contribution.')}</div><p class="table-note">Goal projections use the saved allocation as their starting amount, the selected month as the starting date, and constant nominal returns after assumed fees, before tax and inflation. Account links are for allocation reference; saved amounts are editable in this prototype.</p>`;
}

function forecastPage(){
  return `${pageHead('See the months ahead.',`A cash-flow plan for received income, everyday costs, and planned investments.`,'','CASH FLOW & FORECAST')}<div class="forecast-grid"><div class="card forecast-controls"><h2 class="section-title" style="margin-bottom:20px">Your planning assumptions</h2><form id="forecast-form"><div class="field"><label for="f-cash">Starting household cash (CLP)</label><input id="f-cash" name="closing_cash_clp" type="number" step="1" min="0" value="${n(state.settings.closing_cash_clp)}" required></div><div class="field"><label for="f-neal">${esc(personName('neal'))}’s monthly income (USD)</label><input id="f-neal" name="forecast_income_neal_usd" type="number" step="100" min="0" value="${n(state.settings.forecast_income_neal_usd)}" required><small>Expected payments, not unpaid invoice balances.</small></div><div class="field"><label for="f-partner">${esc(personName('partner'))}’s monthly income (CLP)</label><input id="f-partner" name="forecast_income_partner_clp" type="number" step="1" min="0" value="${n(state.settings.forecast_income_partner_clp)}" required></div><div class="field"><label for="f-expenses">Monthly expenses (CLP)</label><input id="f-expenses" name="forecast_expenses_clp" type="number" step="1" min="0" value="${n(state.settings.forecast_expenses_clp)}" required></div><div class="field"><label for="f-investment">Monthly investment contributions (CLP)</label><input id="f-investment" name="forecast_investment_clp" type="number" step="1" min="0" value="${n(state.settings.forecast_investment_clp)}" required></div><div class="field"><label for="f-fx">Planning exchange rate (CLP per USD)</label><input id="f-fx" name="fx_clp_per_usd" type="number" step="1" min="1" value="${n(state.settings.fx_clp_per_usd)}" required><small>Forecasts only. Saved transaction rates remain unchanged.</small></div><button class="button primary" type="submit">${icon('check')} Save assumptions to Excel</button></form></div><div><div class="card chart-card"><div class="card-header"><div><h2 class="section-title">Projected household cash</h2><p>Six months after ${monthLabel(ui.month)} · ${ui.currency}</p></div><label class="sr-only" for="forecast-case">Freelance income scenario</label><select class="field-input" id="forecast-case"><option value="1">Expected</option><option value="0.7">Conservative</option><option value="1.25">Optimistic</option></select></div><div id="forecast-output">${forecastOutput(true)}</div></div><div class="notice subsection">The scenario changes ${esc(personName('neal'))}’s expected freelance income only: conservative 70%, expected 100%, optimistic 125%. Expenses, exchange rates, and contributions stay at the editable assumptions.</div><div class="notice subsection">Household repayments move money between you and do not change total household cash. Market growth is not counted as spendable income.</div></div></div>`;
}
function forecastValues(fromSettings=false){
  const form=fromSettings?null:$('#forecast-form'),values=form?Object.fromEntries(new FormData(form)):state.settings,multiplier=fromSettings?1:n($('#forecast-case')?.value||1);
  const income=n(values.forecast_income_neal_usd)*n(values.fx_clp_per_usd)*multiplier+n(values.forecast_income_partner_clp),expenses=n(values.forecast_expenses_clp),investments=n(values.forecast_investment_clp),starting=n(values.closing_cash_clp),change=income-expenses-investments;
  return {income,expenses,investments,starting,change,months:Array.from({length:6},(_,i)=>addMonths(ui.month,i+1))};
}
function forecastOutput(fromSettings=false){
  const f=forecastValues(fromSettings),closing=f.starting+f.change*6;
  return `<div class="forecast-total ${closing<0?'stat-negative':''}">${money(closing)}</div><div class="forecast-subtitle">Projected cash after six months · ${f.change>=0?'adding':'using'} ${money(Math.abs(f.change))} per month</div><div style="margin-top:20px">${lineChart([{name:'Projected cash',values:[f.starting,...f.months.map((_,i)=>f.starting+f.change*(i+1))]}],['Now',...f.months.map(m=>monthLabel(m,true))],{height:215,filled:true})}</div><table class="compact-table"><thead><tr><th>Month</th><th class="right">Income</th><th class="right">Expenses</th><th class="right">Investments</th><th class="right">Closing cash</th></tr></thead><tbody>${f.months.map((m,i)=>`<tr><td>${monthLabel(m,true)}</td><td class="right">${money(f.income)}</td><td class="right">${money(f.expenses)}</td><td class="right">${money(f.investments)}</td><td class="right ${f.starting+f.change*(i+1)<0?'stat-negative':''}">${money(f.starting+f.change*(i+1))}</td></tr>`).join('')}</tbody></table>${closing<0?'<div class="notice red" style="margin-top:17px">This scenario runs short of cash. Review expected payment dates, spending, and planned contributions.</div>':''}<p class="forecast-explain">A planning scenario, not a prediction. Assumes equal monthly timing and excludes unentered debt, taxes, irregular costs, and investment returns. Live edits are previews until saved.</p>`;
}

function workbookPage(){
  return `${pageHead('The records stay with you.',`Your local Excel workbook is the source for every view in Casa.`,`<button class="button" data-action="names">${icon('settings')} Household names</button>`,'YOUR WORKBOOK')}<div class="workbook-grid"><div class="card card-pad"><h2 class="section-title">One workbook. A clearer view.</h2><div class="workbook-cover"><div class="workbook-file-icon">${icon('workbook')}</div><div><strong>${esc(state.workbook_name||'Family Finances.xlsx')}</strong><p>Local Excel file · ${state.transactions.length} transactions · ${state.investments.length} investment accounts</p></div></div><div class="workbook-actions"><button class="button primary" data-action="${state.editing_external?'resume-excel':'open-excel'}">${icon(state.editing_external?'refresh':'external')} ${state.editing_external?'Resume app editing':'Edit in Excel'}</button><a class="button" href="/api/export" download="Family Finance Demo.xlsx">${icon('download')} Download workbook</a><button class="button" data-action="reload">${icon('refresh')} Reload</button></div><p class="large-note">App edits save to this workbook. Before each change, Casa checks the file version and creates a dated backup. Nothing is stored in your browser.</p><div class="notice" style="margin-top:21px">${state.editing_external?'App changes are paused. Save and close Excel, then resume app editing to validate and reload the file.':'Use “Edit in Excel” before changing the file directly. This pauses app writes and prevents the two editors from overwriting each other.'}</div></div><div class="card card-pad"><h2 class="section-title">A straightforward workflow</h2><ol class="workflow-steps"><li><span class="step-number">1</span><div><strong>Add records</strong><p>Enter transactions or import a CSV. Review categories and currency details before saving.</p></div></li><li><span class="step-number">2</span><div><strong>Review the month</strong><p>Confirm income, shared spending, and repayments. The net balance carries forward automatically.</p></div></li><li><span class="step-number">3</span><div><strong>Close when ready</strong><p>Closing a month prevents transaction and repayment changes until you reopen it.</p></div></li></ol></div></div><div class="workbook-grid subsection"><div class="card card-pad"><div class="card-header"><h2 class="section-title">Import a CSV</h2><button class="small-link" data-action="sample-csv">Download sample ${icon('download')}</button></div><p class="large-note" style="margin-top:0">This prototype imports CSV records with a preview and duplicate detection. Screenshot and receipt recognition will come in a later version.</p><button class="button" data-action="import" style="margin-top:19px">${icon('upload')} Choose CSV</button></div><div class="card card-pad"><h2 class="section-title">Recent workbook changes</h2><div class="history-list">${[...state.history].reverse().slice(0,10).map(h=>`<div class="history-item"><small>${esc(String(h.timestamp).slice(5,16).replace('T',' '))}</small><p><strong>${esc(h.action)}</strong><br>${esc(h.detail||h.record_id)}</p></div>`).join('')||'<p class="table-note">Your changes will appear here.</p>'}</div></div></div>`;
}

const views={overview:{name:'Overview',render:overviewPage},transactions:{name:'Transactions',render:transactionPage},monthend:{name:'Month',render:monthEndPage},investments:{name:'Investments',render:investmentPage},accounts:{name:'Accounts',render:()=>window.CasaAccounts?window.CasaAccounts.render(accountsContext()):empty('Accounts are loading')},goals:{name:'Goals',render:goalsPage},forecast:{name:'Forecast',render:forecastPage},workbook:{name:'Workbook',render:workbookPage}};
function render(){
  if(!state)return;
  $('#navigation').innerHTML=Object.entries(views).map(([key,v])=>`<button class="nav-item ${ui.view===key?'active':''}" data-view="${key}" aria-label="${esc(v.name)}" ${ui.view===key?'aria-current="page"':''}>${icon(key)}<span>${v.name}</span>${ui.view===key?'<span class="nav-dot"></span>':''}</button>`).join('');
  $('#breadcrumb').textContent=views[ui.view]?.name||'Overview';
  renderReportingControls();
  $('#currency-select').value=ui.currency;
  $('#refresh-button').innerHTML=icon('refresh');
  $('#refresh-button').title=googleMaster()?'Refresh master Sheet':'Reload workbook';
  $('#refresh-button').setAttribute?.('aria-label',googleMaster()?'Refresh master Sheet':'Reload workbook');
  $('#external-banner').hidden=!state.editing_external;
  if(state.editing_external){
    if(googleMaster()){
      const storage=state.storage;
      $('#external-banner').innerHTML=storage.online===false?'<span>Google is unavailable. Showing the last verified cloud records read-only. Refresh when reconnected to edit again.</span><button class="button small" data-action="reload">Refresh Google</button>':storage.pending_write?'<span>A cloud save needs verification. Refresh before making another change.</span><button class="button small" data-action="reload">Verify save</button>':storage.verification_error?'<span>Google records need verification before app editing can resume.</span><button class="button small" data-view="workbook">Check connection</button>':'<span>Direct Google Sheets editing · app changes are paused. Finish your Sheet edits, then resume.</span><button class="button small" data-action="resume-excel">Resume app editing</button>';
    }else $('#external-banner').innerHTML=`<span>Excel editing mode · app changes are paused. Save and close the workbook, then resume.</span><button class="button small" data-action="resume-excel">Resume app editing</button>`;
  }
  $('#content').innerHTML=(views[ui.view]||views.overview).render();
  $('#save-status').textContent=googleMaster()?`${state.storage.online===false?'Offline · verified cloud cache':state.editing_external?'Google Sheets · read-only':'Connected to Google Sheets'} · ${state.workbook_name||'Family finances'}`:`${state.editing_external?'Excel editing mode':'Connected to local Excel'} · ${state.workbook_name||'Family Finances.xlsx'}`;
  if(googleMaster()){
    const sidebar=document.querySelector('.sidebar-bottom');
    if(sidebar)sidebar.innerHTML='<button class="button documents-sidebar" type="button" data-upload-documents>Upload documents</button><div class="local-indicator"><span></span>Google Sheets master</div><p>Documents wait in Inbox.<br>Analysis happens when you ask.</p><div class="demo-mark">Private household records</div>';
    for(const button of document.querySelectorAll('#content button'))if(/\b(?:Save|saved|Save assumptions).*\bExcel\b/.test(button.textContent))button.textContent=button.textContent.replace(/\bExcel\b/g,'Google Sheets');
  }
  mountMonthlyAnalysis();
  if(ui.view==='investments')window.CasaPortfolio?.mount(investmentContext());
  if(ui.view==='forecast')window.CasaPlanning?.mount(investmentContext());
  if(ui.view==='accounts')window.CasaAccounts?.mount(accountsContext());
  if(ui.view==='transactions')window.CasaTransactionFilters?.mount({selection:transactionSelection(),onChange:applyTransactionFilters});
  if(ui.view==='workbook')window.CasaCloud?.mount(cloudContext());
  if(ui.view==='review')window.CasaReview?.mount(reviewContext());
  if(state.editing_external){for(const element of document.querySelectorAll('#content [data-action="new-transaction"],#content [data-action="new-investment"],#content [data-action="new-goal"],#content [data-action="import"],#content [data-edit],#content [data-edit-investment],#content [data-edit-goal],#content [data-account-add],#content [data-account-edit],#content [data-month-income],#content [data-review-resolve]')){if(element.tagName==='BUTTON')element.disabled=true;else{element.setAttribute('aria-disabled','true');element.setAttribute('tabindex','-1');}}}
  window.CasaNavigation?.record(navigationSnapshot());
}
function navigationSnapshot(){return Object.fromEntries(['view','month','period','currency','person','category','kind','transactionFilters','search','showExcluded','reviewAll'].map(key=>[key,ui[key]??(['showExcluded','reviewAll'].includes(key)?false:'')]));}

function openModal(title,body,footer='',onSubmit=null,modal=true){
  if(googleMaster()){footer=footer.replace(/\bExcel\b/g,'Google Sheets');}
  const dialog=$('#modal');
  dialog.classList.toggle('documents-dialog',!modal);
  $('#modal-content').innerHTML=`<form id="modal-form"><div class="modal-header"><h2>${title}</h2><button class="icon-button" type="button" data-close-modal aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body"><div class="modal-error" id="modal-error" role="alert"></div>${body}</div><div class="modal-footer"><button class="button" type="button" data-close-modal>Cancel</button>${footer}</div></form>`;
  $('#modal-form').addEventListener('submit',async e=>{e.preventDefault();if(!onSubmit)return;const btn=e.submitter;try{if(btn)btn.disabled=true;$('#modal-error').textContent='';await onSubmit(new FormData(e.target));dialog.close();}catch(error){$('#modal-error').textContent=error.message;if(btn)btn.disabled=false;}});
  if(!dialog.open){dialog.setAttribute('aria-modal',String(modal));if(modal)dialog.showModal();else dialog.show();}
}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="m-${name}">${label}</label><input id="m-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function selectField(label,name,options,value){return `<div class="field"><label for="m-${name}">${label}</label><select id="m-${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
function guardEditing(){if(googleMaster()&&(state.storage?.online===false||state.storage?.read_only||state.editing_external))throw new Error(state.storage?.online===false?'Reconnect Google and refresh before making changes. Saved cloud records are read-only offline.':state.storage?.pending_write?'A cloud save needs verification. Refresh before making another change.':'App editing is paused. Finish direct Google Sheets edits, then resume app editing.');if(state.editing_external)throw new Error('Save and close Excel, then resume app editing before making changes.');}
function transactionModal(id=null){
  guardEditing();const t=id?state.transactions.find(t=>t.id===id):{date:`${ui.month}-15`,person:ui.person==='partner'?'partner':'neal',kind:'expense',merchant:'',category_id:activeCategories()[0]?.id||'',sharing:'needs_review',amount:'',currency:'CLP',charged_amount:'',charged_currency:'CLP',fx_clp_per_usd:null,notes:'',included:true};
  if(closedMonths().includes(monthKey(t.date)))throw new Error('This month is closed. Reopen it from Month before editing transactions.');
  openModal(id?'Edit transaction':'Add transaction',`<p class="modal-description">Keep the original purchase and the bank’s final charge. Shared purchases feed the month-end total.</p><div class="field-row">${field('Date','date',dateKey(t.date),'date','required')}${selectField('Person','person',[['neal',personName('neal')],['partner',personName('partner')]],t.person)}</div><div class="field-row">${selectField('Type','kind',[['expense','Expense'],['refund','Refund / spending offset'],['income','Income recorded'],['transfer','Transfer / funding'],['transfer_review','Transfer purpose unresolved'],['investment_transfer','Investment funding'],['possible_duplicate','Possible duplicate'],['duplicate_conflict','Duplicate conflict']],t.kind)}${selectField('Category','category_id',state.categories.filter(c=>!isTrue(c.archived)||c.id===t.category_id).map(c=>[c.id,c.name]),t.category_id)}</div>${field('Merchant or income description','merchant',t.merchant,'text','required maxlength="150"')}<div class="field-row">${field('Original amount','amount',t.amount,'number','required min="0" step="0.01"')}${selectField('Original currency','currency',[['CLP','CLP'],['USD','USD']],t.currency)}</div><div class="field-row">${field('Bank-charged / received amount','charged_amount',t.charged_amount,'number','required min="0" step="0.01"')}${selectField('Charged / received currency','charged_currency',[['CLP','CLP'],['USD','USD']],t.charged_currency)}</div><div class="field-row">${field('Saved exchange rate (CLP per USD)','fx_clp_per_usd',t.fx_clp_per_usd??'','number','min="0.01" step="0.01"')}${selectField('Household use','sharing',[['needs_review','Needs sharing review'],['shared','Shared household expense'],['personal','Personal / income']],t.sharing)}</div>${selectField('Include in totals','included',[['true','Include this record'],['false','Exclude duplicate / non-spending source']],isIncluded(t)?'true':'false')}${field('Rate date (optional)','fx_date',t.fx_date||'','date')}${field('Rate source (optional)','fx_source',t.fx_source||'')}${field('Notes (optional)','notes',t.notes)}<p class="table-note">${esc(t.source_file||'Manual record')} ${esc(t.fx_source||'')} ${esc(t.fx_date||'')}</p>`,`<button class="button primary" type="submit">Save to Excel</button>`,async data=>{const transaction={...t,...Object.fromEntries(data)};['amount','charged_amount'].forEach(k=>transaction[k]=n(transaction[k]));transaction.fx_clp_per_usd=known(transaction.fx_clp_per_usd)?n(transaction.fx_clp_per_usd):null;transaction.included=transaction.included==='true';if(transaction.kind==='income')transaction.sharing='personal';if(!id)delete transaction.id;await mutate('/api/transaction',{transaction});});
  if(!id){for(const [from,to] of [['amount','charged_amount'],['currency','charged_currency']])$(`#m-${from}`).addEventListener('change',()=>{const target=$(`#m-${to}`);if(!target.value||from==='currency')target.value=$(`#m-${from}`).value;});}
}
function repaymentModal(){
  guardEditing();const c=cumulative(ui.month),from=c.balance>=0?'neal':'partner';
  openModal('Record a repayment',`<p class="modal-description">Record money already transferred. This reduces the balance between you without adding income or expenses.</p><div class="field-row">${field('Transfer date','date',`${ui.month}-28`,'date','required')}${selectField('From','from_person',[['neal',personName('neal')],['partner',personName('partner')]],from)}</div>${field('Amount (CLP)','amount_clp',c.unresolved?'':Math.abs(c.balance),'number','required min="1" step="1"')}${field('Note (optional)','notes','','text','maxlength="150"')}<div class="notice">Cumulative balance: ${c.unresolved?'unresolved':`${esc(direction(c.balance))} ${money(Math.abs(c.balance))}`}. You can record a partial repayment.</div>`,`<button class="button primary" type="submit">Record repayment</button>`,async data=>{const settlement=Object.fromEntries(data);settlement.to_person=settlement.from_person==='neal'?'partner':'neal';settlement.amount_clp=n(settlement.amount_clp);await mutate('/api/settlement',{settlement},'Repayment recorded in Excel');});
}
function categoriesModal(){
  guardEditing();openModal('Manage categories',`<p class="modal-description">Renaming keeps historical transactions linked. Archive a category to remove it from new transaction choices.</p><div class="modal-categories">${activeCategories().map(c=>`<div class="category-edit-row"><input type="color" data-cat-color="${esc(c.id)}" value="${esc(c.color||'#7b9b6a')}" aria-label="${esc(c.name)} color"><input data-cat-name="${esc(c.id)}" value="${esc(c.name)}" aria-label="${esc(c.name)} name"><input type="number" min="0" step="1" data-cat-budget="${esc(c.id)}" value="${n(c.budget_clp)}" aria-label="${esc(c.name)} monthly budget CLP"><div class="inline-form-actions"><button type="button" class="icon-button" data-save-category="${esc(c.id)}" aria-label="Save ${esc(c.name)}">${icon('check')}</button><button type="button" class="icon-button" data-archive-category="${esc(c.id)}" aria-label="Archive ${esc(c.name)}">${icon('archive')}</button></div></div>`).join('')}</div><h3 class="modal-subtitle">Add a category</h3><div class="field-row">${field('Category name','name','','text','required maxlength="60"')}${field('Monthly budget (CLP)','budget_clp',0,'number','min="0" step="1"')}</div>${field('Color','color','#7b9b6a','color')}<p class="table-note">${state.categories.filter(c=>isTrue(c.archived)).length} archived categories remain in historical records. Budgets are household monthly amounts.</p>`,`<button class="button primary" type="submit">Add category</button>`,async data=>{const c=Object.fromEntries(data);c.budget_clp=n(c.budget_clp);c.archived=false;await mutate('/api/category',{category:c},'Category added');});
}
function goalModal(id=null){
  guardEditing();const g=id?state.goals.find(g=>g.id===id):{person:ui.person==='all'?'family':ui.person,name:'',target:'',currency:'USD',saved:null,monthly_contribution:null,target_date:'',annual_return:null,linked_account_id:''};
  openModal(id?'Edit goal':'Add a life goal',`<div class="field-row">${field('Goal name','name',g.name,'text','required maxlength="100"')}${selectField('For','person',[['family','Family'],['neal',personName('neal')],['partner',personName('partner')]],g.person)}</div><div class="field-row">${field('Target amount','target',g.target??'','number','min="1" step="0.01"')}${selectField('Goal currency','currency',[['CLP','CLP'],['USD','USD']],g.currency)}</div><div class="field-row">${field('Allocated savings today','saved',g.saved??'','number','min="0" step="0.01"')}${field('Monthly contribution','monthly_contribution',g.monthly_contribution??'','number','min="0" step="0.01"')}</div><div class="field-row">${field('Target date','target_date',dateKey(g.target_date),'date','')}${field('Assumed annual return after fees (%)','annual_return',known(g.annual_return)?n(g.annual_return)*100:'','number','min="-50" max="30" step="0.1"')}</div>${selectField('Reference investment account','linked_account_id',[['','No linked account'],...state.investments.map(a=>[a.id,`${personName(a.person)} · ${a.name}`])],g.linked_account_id)}<div class="notice">Allocated savings are part of existing assets. They are not added to the household portfolio total.</div>`,`<button class="button primary" type="submit">Save goal to Excel</button>`,async data=>{const goal={...g,...Object.fromEntries(data)};['target','saved','monthly_contribution'].forEach(k=>goal[k]=known(goal[k])?n(goal[k]):null);goal.annual_return=known(goal.annual_return)?n(goal.annual_return)/100:null;if(!id)delete goal.id;await mutate('/api/goal',{goal});});
}
function investmentModal(id=null){
  if(window.CasaAccounts){if(id)window.CasaAccounts.edit(accountsContext(),id);else window.CasaAccounts.add(accountsContext());return;}
  guardEditing();const a=id?state.investments.find(a=>a.id===id):{person:ui.person==='partner'?'partner':'neal',name:'',type:'Brokerage',currency:'USD',balance:null,monthly_contribution:null,annual_return:null,annual_fee:null,equity_fraction:null,single_asset_fraction:null};
  openModal(id?'Edit investment assumptions':'Add investment account',`<p class="modal-description">These are planning records, not investment orders. Historical snapshots remain unchanged when assumptions change.</p><div class="field-row">${field('Account label','name',a.name,'text','required maxlength="100"')}${selectField('Person','person',[['neal',personName('neal')],['partner',personName('partner')],['family','Family']],a.person)}</div><div class="field-row">${selectField('Account purpose','type',[['Brokerage','Brokerage'],['Retirement','Retirement'],['Life goal','Life goal'],['Cash management','Cash management'],['Education','Education'],['Cash','Cash'],['Other','Other']],a.type)}${id?`<div class="field"><label for="m-currency-readonly">Currency</label><input id="m-currency-readonly" value="${esc(a.currency)}" readonly><input name="currency" type="hidden" value="${esc(a.currency)}"><small>Historical account currency stays unchanged.</small></div>`:selectField('Currency','currency',[['CLP','CLP'],['USD','USD']],a.currency)}</div>${!id?field('Starting balance (creates initial snapshot)','balance',a.balance??'','number','min="0" step="0.01"'):''}<div class="field-row">${field('Monthly contribution','monthly_contribution',a.monthly_contribution??'','number','min="0" step="0.01"')}${field('Assumed annual return before fees (%)','annual_return',known(a.annual_return)?n(a.annual_return)*100:'','number','min="-50" max="30" step="0.1"')}</div><div class="field-row">${field('Annual fees (%)','annual_fee',known(a.annual_fee)?n(a.annual_fee)*100:'','number','min="0" max="10" step="0.01"')}${field('Equity allocation (%)','equity_fraction',known(a.equity_fraction)?n(a.equity_fraction)*100:'','number','min="0" max="100" step="1"')}</div>${field('Largest single-asset allocation (%)','single_asset_fraction',known(a.single_asset_fraction)?n(a.single_asset_fraction)*100:'','number','min="0" max="100" step="1"')}<p class="table-note">Avoid account numbers and institution names. Use a descriptive account label.</p>`,`<button class="button primary" type="submit">Save account to Excel</button>`,async data=>{const investment={...a,...Object.fromEntries(data)};['balance','monthly_contribution'].forEach(k=>investment[k]=known(investment[k])?n(investment[k]):null);['annual_return','annual_fee','equity_fraction','single_asset_fraction'].forEach(k=>investment[k]=known(investment[k])?n(investment[k])/100:null);if(!id)delete investment.id;await mutate('/api/investment',{investment});ui.projectionRate=null;ui.projectionMonthly=null;render();});
}
