document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-edit],[data-drill-category],[data-select-month],[data-chart-month]')&&!e.target.matches('button,a,input,select,textarea')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-tooltip]');if(!el)return;const wrap=el.closest('.chart-wrap'),tip=wrap.querySelector('.chart-tooltip');if(!tip)return;const r=el.getBoundingClientRect(),wr=wrap.getBoundingClientRect();tip.textContent=el.dataset.tooltip;tip.style.left=`${Math.min(wr.width-70,Math.max(70,r.left-wr.left+r.width/2))}px`;tip.style.top=`${Math.max(20,r.top-wr.top)}px`;tip.hidden=false;});
