window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(views[view]&&ui.view!==view){ui.view=view;if(!supportsAnnualReport(view))ui.period='month';render();}});
/* Real-data views. Missing information stays missing; it is never a zero balance. */
const known = v => v!==null && v!==undefined && v!=='' && Number.isFinite(Number(v));
const isIncluded = t => ![false,0,'FALSE','false','no'].includes(t.included);
const liveRows = (month=ui.month,person=ui.person) => state.transactions.filter(t=>isIncluded(t)&&monthKey(t.date)===month&&(person==='all'||person===t.person));
const netSign = t => t.kind==='refund'?-1:1;
const isSpend = t => ['expense','refund'].includes(t.kind);
const nullableSum = values => values.some(v=>v===null)?null:values.reduce((a,v)=>a+v,0);
// Reporting estimates never overwrite a bank charge or the workbook's verified rate.
function reportingRate(t){
  if(known(t.fx_clp_per_usd)&&n(t.fx_clp_per_usd)>0)return {rate:n(t.fx_clp_per_usd),estimated:isTrue(t.fx_estimate),label:t.fx_basis||'Saved transaction rate'};
  if(String(t.date_basis||'').includes('ambiguous')&&known(t.legacy_fx_rate)&&n(t.legacy_fx_rate)>0)return {rate:n(t.legacy_fx_rate),estimated:true,label:'Original spreadsheet rate; transaction date or bank conversion unverified'};
  const prior=(state.exchange_rates||[]).filter(q=>q.date<=dateKey(t.date)&&known(q.clp_per_usd)).sort((a,b)=>b.date.localeCompare(a.date))[0];
  if(prior)return {rate:n(prior.clp_per_usd),estimated:true,label:`Estimate using latest available SII reference, ${prior.date}. Actual bank charge unchanged.`};
  return known(t.legacy_fx_rate)&&n(t.legacy_fx_rate)>0?{rate:n(t.legacy_fx_rate),estimated:true,label:'Original spreadsheet reporting rate; unverified'}:null;
}
const rowAmount = (t,currency=ui.currency) => {
  if(t.charged_currency===currency)return n(t.charged_amount);
  const q=reportingRate(t);if(!q)return null;
  return currency==='CLP'?n(t.charged_amount)*q.rate:n(t.charged_amount)/q.rate;
};
const transactionDisplay = t => {const v=rowAmount(t);return v===null?nativeMoney(t.charged_amount,t.charged_currency):`${t.charged_currency!==ui.currency&&reportingRate(t)?.estimated?'≈ ':''}${nativeMoney(v,ui.currency)}`;};
const recordedTotal = rows => nullableSum(rows.map(t=>{const value=rowAmount(t);return value===null?null:value*netSign(t)}));
const missingText = value => known(value)?value:'';
const asOf = value => value?dayLabel(value)+' '+dateKey(value).slice(0,4):'Date not provided';
const reviewCount = () => state.review.filter(r=>!['resolved','closed','dismissed'].includes(String(r.status||'open').toLowerCase())).length;
const reportRows = (person=ui.person) => state.transactions.filter(t=>isIncluded(t)&&inReport(t.date)&&(person==='all'||person===t.person));
const liveTotals = () => {
  const rows=reportRows();
  const income=recordedTotal(rows.filter(t=>t.kind==='income')),expenses=recordedTotal(rows.filter(isSpend));
  return {rows,income,expenses,surplus:income===null||expenses===null?null:income-expenses};
};
function liveMonthlyChart(){
  const months=isYearReport()?Array.from({length:12},(_,index)=>reportYear()+'-'+String(index+1).padStart(2,'0')):allMonths().filter(m=>m<=ui.month).slice(-8),series=months.map(month=>{
    const rows=liveRows(month);
    const income=rows.filter(t=>t.kind==='income'),spending=rows.filter(isSpend);
    return {month,income:income.length?recordedTotal(income):null,spending:spending.length?recordedTotal(spending):null};
  });
  if(window.CasaOverviewCharts)return window.CasaOverviewCharts.trend({series,currency:ui.currency,formatMoney:value=>nativeMoney(value,ui.currency),formatCompact:compact,monthLabel,subtitle:`${personName(ui.person)} · ${ui.currency} · ${isYearReport()?reportYear()+' by month':'last eight recorded months'}`});
  const width=680,height=230,left=65,right=15,top=22,bottom=38,innerW=width-left-right,innerH=height-top-bottom;
  const max=Math.max(1,...series.flatMap(s=>[s.income??0,s.spending??0]))*1.1;
  const group=innerW/Math.max(1,series.length),bar=Math.min(20,group*.28),y=value=>top+innerH-Math.max(0,value)/max*innerH;
  let svg=`<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Recorded monthly income and spending in ${ui.currency}">`;
  for(let i=0;i<4;i++){const value=max*i/3,yy=y(value);svg+=`<line class="chart-grid" x1="${left}" x2="${width-right}" y1="${yy}" y2="${yy}"/><text class="chart-label" x="${left-9}" y="${yy+3}" text-anchor="end">${esc(compact(value))}</text>`}
  series.forEach((s,i)=>{const x=left+group*i+group/2;[['income','var(--chart-income,#0d9488)',-bar-2],['spending','var(--chart-spending,#94a3b8)',2]].forEach(([key,color,offset])=>{
    const value=s[key];
    svg+=value===null?`<text class="chart-label" x="${x+offset+bar/2}" y="${top+innerH-8}" text-anchor="middle" transform="rotate(-90 ${x+offset+bar/2} ${top+innerH-8})">Not recorded</text>`:`<rect class="chart-bar" x="${x+offset}" y="${y(value)}" height="${Math.max(0,value)/max*innerH}" width="${bar}" rx="3" fill="${color}" data-chart-month="${s.month}" ${tooltipAttrs(`${monthLabel(s.month)} · ${key}: ${nativeMoney(value,ui.currency)}`)}/>`;
  });svg+=`<text class="chart-label" x="${x}" y="${height-9}" text-anchor="middle">${monthLabel(s.month,true)}</text>`});
  return `<div class="chart-wrap">${svg}</svg><div class="chart-tooltip" hidden></div></div>`;
}
function unavailable(value,currency=ui.currency){return value===null||value===undefined?'Amount not supplied':nativeMoney(value,currency)}
function liveOverview(){
  const t=liveTotals(),unknown=t.rows.filter(r=>rowAmount(r)===null&&r.kind!=='transfer').length;
  const invoice=t.rows.some(r=>String(r.date_basis||'').includes('invoice'));
  const categories=Object.values(t.rows.filter(isSpend).reduce((acc,r)=>{acc[r.category_id]??={...category(r.category_id),values:[]};acc[r.category_id].values.push(rowAmount(r)===null?null:rowAmount(r)*netSign(r));return acc},{})).map(c=>({...c,total:nullableSum(c.values)})).sort((a,b)=>(b.total||0)-(a.total||0));
  const recordStats=[['Included transactions',t.rows.length],['Excluded source records',state.transactions.filter(r=>inReport(r.date)&&(ui.person==='all'||r.person===ui.person)&&!isIncluded(r)).length],['Without a reporting estimate',unknown],['Sharing decisions pending',t.rows.filter(r=>isSpend(r)&&r.sharing==='needs_review').length]];
  return `${pageHead('Your family finances',`${reportLabel()} · a clearer picture of your household.`,`<button class="button" type="button" data-upload-documents>${icon('upload')} Upload documents</button><button class="button primary" data-action="new-transaction">${icon('plus')} Add transaction</button>`)}
    ${personTabs()}
    <div class="metrics-grid">${metric('Income recorded',unavailable(t.income),`Income supplied for ${isYearReport()?'this year':'this month'}`,'income')}${metric('Recorded spending · ≈',unavailable(t.expenses),'After refunds · includes reporting estimates','expense')}${metric('Income less spending',unavailable(t.surplus),'Before investing · based on supplied records','wallet')}${metric('Original currency totals',nativeSpendSummary(t.rows),'Actual charges · no conversion applied','wallet')}</div>
    <div class="overview-first">${isYearReport()?annualSettlementHero():practicalSettlementHero()}<div class="card card-pad record-card"><div class="card-header"><div><h2 class="section-title">Behind the numbers</h2><p>Coverage of ${isYearReport()?'this year’s':'this month’s'} records</p></div><button class="small-link" data-view="review">Review ${reviewCount()} items ${icon('arrow')}</button></div><div class="record-stats">${recordStats.map(([label,value])=>`<div class="record-stat"><strong class="record-stat-value">${value}</strong><span>${label}</span></div>`).join('')}</div><p class="table-note">Your original bank charges are always retained. Missing records can affect totals and comparisons.</p></div></div>
    <details class="record-notes"><summary>${icon('info')}<span>Record notes</span><span class="record-note-tags">≈ Estimated conversions${invoice?' · Invoice-month income':''}</span></summary><div><p>Amounts marked ≈ include estimated conversions using the original spreadsheet rate or the latest available published reference. These estimates do not change your actual charges.</p>${invoice?'<p>Freelance income is provisionally grouped by invoice month. This is not verified received cash; payment dates remain to be confirmed.</p>':''}<button class="small-link" data-view="review">Review ${reviewCount()} open items</button></div></details>
    <div class="card chart-card subsection">${liveMonthlyChart()}${window.CasaOverviewCharts?'':'<p class="table-note">Select a month’s bar to explore its records. Reporting conversions may be estimated; recorded income may be incomplete or provisionally assigned by invoice month.</p>'}</div>
    <div class="section-grid subsection"><div class="card card-pad">${window.CasaOverviewCharts?window.CasaOverviewCharts.categories({categories,currency:ui.currency,formatMoney:value=>unavailable(value),categoryLabel,subtitle:`${isYearReport()?reportYear()+' · ':''}Recorded spending by category`}):`<div class="card-header"><div><h2 class="section-title">Where your money went</h2><p>Recorded spending by category</p></div></div><div class="spending-category-list">${categories.map(c=>`<div class="explain-row category-spending-row" data-drill-category="${esc(c.id)}" role="button" tabindex="0">${categoryLabel(c)}${amountChip(unavailable(c.total),true)}</div>`).join('')||empty('No included spending records')}</div>`}</div><div class="card card-pad"><div class="card-header"><div><h2 class="section-title">Recent activity</h2><p>The latest movements ${isYearReport()?'this year':'this month'}</p></div><button class="small-link" data-view="transactions">View all ${icon('arrow')}</button></div>${liveRecent(t.rows)}</div></div>
    <details class="card card-pad subsection cash-snapshots"><summary><span class="section-title">Saved cash snapshots</span><span class="muted">Source balances</span></summary><p class="table-note">Source values, not current bank feeds. These may overlap with other source screenshots and are not added to investments as net worth.</p>${(state.balances||[]).map(b=>`<div class="explain-row"><span>${esc(b.name||b.account_label||'Cash snapshot')} · ${esc(personName(b.person))}<small class="muted" style="display:block">${b.as_of?asOf(b.as_of):'Date not provided'} · ${esc(b.source_file||'')}</small></span>${amountChip(nativeMoney(b.balance,b.currency))}</div>`).join('')||empty('No confirmed cash snapshots')}</details>`;
}
function liveRecent(rows){
  return `<table class="compact-table activity-table"><thead><tr><th>Activity</th><th class="right">Amount</th></tr></thead><tbody>${[...rows].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6).map(t=>`<tr data-edit="${esc(t.id)}" tabindex="0"><td><div class="transaction-description"><strong>${esc(t.merchant||'Description not supplied')}</strong><small>${dayLabel(t.date)} · ${esc(personName(t.person))}</small></div></td><td class="right">${amountChip(transactionDisplay(t),true)}</td></tr>`).join('')}</tbody></table>`;
}
function transactionSelection(){
  let selection;
  try{if(ui.transactionFilters)selection=JSON.parse(ui.transactionFilters);}catch{}
  selection??={categories:ui.category==='all'?[]:[ui.category],types:ui.kind==='all'?[]:ui.kind==='spending'?['expense','refund']:[ui.kind],dateFrom:'',dateTo:''};
  return window.CasaTransactionFilters?window.CasaTransactionFilters.normalize(selection):selection;
}
function applyTransactionFilters(selection){ui.transactionFilters=JSON.stringify(selection);ui.category='all';ui.kind='all';render();}
function clearTransactionDates(){const selection=transactionSelection();if(selection.dateFrom||selection.dateTo){selection.dateFrom='';selection.dateTo='';ui.transactionFilters=JSON.stringify(selection);}}
function transactionPeriodLabel(){const selection=transactionSelection();return selection.dateFrom||selection.dateTo?`${selection.dateFrom||'First record'} to ${selection.dateTo||'Latest record'} · custom range`:reportLabel();}
function transactionDateLabel(date){const selection=transactionSelection();return selection.dateFrom||selection.dateTo?new Date(dateKey(date)+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):dayLabel(date);}
function filteredTransactionRows(){
  const selection=transactionSelection(),custom=!!(selection.dateFrom||selection.dateTo);
  return state.transactions.filter(t=>(custom||inReport(t.date))&&(ui.person==='all'||t.person===ui.person)&&(ui.showExcluded||isIncluded(t))&&(window.CasaTransactionFilters?window.CasaTransactionFilters.matches(t,selection):(!selection.categories.length||selection.categories.includes(t.category_id))&&(!selection.types.length||selection.types.includes(t.kind)))&&`${t.merchant} ${t.notes||''} ${t.order_details||''} ${JSON.stringify(state.source_evidence?.[t.id]||[])} ${category(t.category_id).name}`.toLowerCase().includes(ui.search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));
}
function liveTransactions(){
  const rows=filteredTransactionRows();
  return `${pageHead('Every transaction, in one place.',`${transactionPeriodLabel()} · select a row to edit its details.`,`<button class="button" data-action="categories">${icon('settings')} Categories</button><button class="button" data-action="import">${icon('upload')} Import CSV</button><button class="button primary" data-action="new-transaction">${icon('plus')} Add transaction</button>`)}${personTabs()}
    <div class="toolbar"><div class="search-field">${icon('search')}<label class="sr-only" for="transaction-search">Search transactions</label><input id="transaction-search" value="${esc(ui.search)}" placeholder="Search transactions…"></div><label class="excluded-toggle"><input type="checkbox" id="show-excluded" ${ui.showExcluded?'checked':''}> Show excluded</label></div>
    ${window.CasaTransactionFilters?window.CasaTransactionFilters.render({categories:state.categories.map(c=>({...c,name:(window.CasaCategories?.visual(c).emoji||'')+' '+c.name})),types:[...new Set(state.transactions.map(t=>t.kind))],selection:transactionSelection()}):''}
    <div class="card table-card"><div class="table-scroll"><table class="data-table transaction-table"><thead><tr><th>Date</th><th>Description</th><th>Person</th><th>Category</th><th>Household use</th><th class="right">Amount</th></tr></thead><tbody>${rows.map(t=>`<tr data-edit="${esc(t.id)}" tabindex="0" aria-label="Edit ${esc(t.merchant||'Description not supplied')}"><td>${transactionDateLabel(t.date)}</td><td><div class="transaction-description"><strong>${esc(t.merchant||'Description not supplied')}</strong>${window.CasaEvidence?.render(t,state)||''}<details class="source-details"><summary>Source & charge details</summary><p>${esc(t.source_file||'Manual entry')}${t.source_row?` · row ${esc(t.source_row)}`:''}<br>${nativeMoney(t.charged_amount,t.charged_currency)} charged${t.currency!==t.charged_currency?` · original ${nativeMoney(t.amount,t.currency)}`:''}</p></details></div></td><td><span class="person-badge ${t.person==='partner'?'partner':''}">${esc(personName(t.person))}</span></td><td>${categoryLabel(t.category_id)}</td><td><span class="pill ${t.sharing==='needs_review'?'amber':t.sharing==='shared'?'':'neutral'}">${!isIncluded(t)?'Excluded':t.kind==='income'?'Income':t.kind==='transfer'?'Transfer':t.sharing==='needs_review'?'Sharing needed':t.sharing==='shared'?'Shared':'Personal'}</span></td><td class="right" title="${esc(reportingRate(t)?.label||'Original charged amount')}">${amountChip((t.kind==='refund'||t.kind==='income'?'+':t.kind==='transfer'?'':'−')+transactionDisplay(t),true)}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('No matching transactions','Try another filter or month.')}</div><div class="table-footer"><span>${rows.length} records</span><span class="table-total">Net spending ${amountChip(unavailable(recordedTotal(rows.filter(t=>isIncluded(t)&&isSpend(t)))) )}</span></div></div>
    <details class="record-notes subsection"><summary>${icon('info')}<span>How these totals work</span></summary><div><p>Transfers, excluded duplicates, and credit-card payments do not count as spending. Refunds reduce spending. ≈ means an estimated exchange-rate conversion. Original charges and source references are retained in each row’s details. Unclassified transfers and source gaps are listed in Review.</p></div></details>`;
}
function nativeSpendSummary(rows){return '<span class="amount-stack">'+['USD','CLP'].map(c=>{const v=sum(rows.filter(t=>isSpend(t)&&t.charged_currency===c),t=>netSign(t)*n(t.charged_amount));return '<span>'+nativeMoney(v,c)+'</span>'}).join('')+'</span>'}
function workingMonth(month){
 const rows=liveRows(month,'all');
 const total=rs=>nullableSum(rs.map(t=>{const v=rowAmount(t,'CLP');return v===null?null:v*netSign(t)}));
 const incomes={};for(const person of ['neal','partner']){const r=rows.filter(t=>t.person===person&&t.kind==='income');incomes[person]=r.length?total(r):null}
 const missing=['neal','partner'].filter(p=>incomes[p]===null);
 const sharedRows=rows.filter(t=>isSpend(t)&&t.sharing==='shared'),shared=total(sharedRows),paid=total(sharedRows.filter(t=>t.person==='neal'));
 const ratio=missing.length===0&&incomes.neal+incomes.partner>0?incomes.neal/(incomes.neal+incomes.partner):null;
 const repayments=sum(state.settlements.filter(r=>monthKey(r.date)===month),r=>n(r.amount_clp)*(r.from_person==='neal'?1:-1));
 const estimate=ratio!==null&&shared!==null&&paid!==null?roundCLP(shared*ratio-paid)-repayments:null;
 return {rows,incomes,missing,shared,paid,ratio,estimate,pending:rows.filter(t=>isSpend(t)&&t.sharing==='needs_review').length};
}
function practicalSettlementHero(large=false){
 const w=workingMonth(ui.month),s=monthSummary(ui.month),final=s.remaining!==null;
 const value=final?s.remaining:w.estimate;
 return `<div class="card settlement-hero ${large?'large':''}"><div class="hero-top"><h2 class="section-title">${large?'Your monthly estimate':'Between the two of you'}</h2><span class="subtle-tag">${final?'Confirmed':'Working estimate'}</span></div><div class="hero-caption">${value===null?'Add '+w.missing.map(personName).join(' and ')+"’s income":esc(direction(value))}</div><div class="hero-value ${value===null?'hero-message':'hero-amount'}">${value===null?'One income figure needed':(final?'':'≈ ')+nativeMoney(Math.abs(value),'CLP')}</div><p>${value===null?'The spending is recorded. Enter the missing monthly income to calculate your proportional split.':`Based on classified shared expenses${w.pending?`; ${w.pending} purchases are still unallocated`:''}.`}</p><div class="hero-bottom"><p>${monthLabel(ui.month)} only. Earlier unpaid balances are separate. ${["neal","partner"].filter(p=>!w.rows.some(t=>t.person===p&&isSpend(t))).map(p=>esc(personName(p))+" has no spending records for this month; their payments are not established.").join(" ")}</p><button class="button" ${value===null?'data-month-income="'+w.missing[0]+'"':large?'data-view="review"':'data-view="monthend"'}>${value===null?'Enter income':large?'Review records':'See calculation'}</button></div></div>`;
}
function yearSettlement(){
  const months=reportMonths().filter(month=>liveRows(month,'all').some(row=>isSpend(row)||row.kind==='income')||state.settlements.some(row=>monthKey(row.date)===month));
  const estimates=months.map(month=>{const working=workingMonth(month),confirmed=monthSummary(month).remaining;return {month,value:confirmed??working.estimate,confirmed:confirmed!==null};});
  const available=estimates.filter(row=>row.value!==null);
  return {estimates,available,missing:estimates.length-available.length,total:available.length?sum(available,row=>row.value):null};
}
function annualSettlementHero(){
  const summary=yearSettlement(),partial=summary.missing>0;
  return `<div class="card settlement-hero"><div class="hero-top"><h2 class="section-title">Between the two of you</h2><span class="subtle-tag">${esc(reportYear())} · monthly results</span></div><div class="hero-caption">${summary.total===null?'Monthly income needed':(partial?'Known subtotal · ':'')+esc(direction(summary.total))}</div><div class="hero-value ${summary.total===null?'hero-message':'hero-amount'}">${summary.total===null?'No estimate yet':'≈ '+nativeMoney(Math.abs(summary.total),'CLP')}</div><p>${partial?'Subtotal of '+summary.available.length+' calculable months; '+summary.missing+' recorded months still need income or conversion details.':'Sum of the recorded monthly results, after recorded repayments.'}</p><details class="annual-month-results"><summary>Review ${summary.estimates.length} recorded months</summary>${summary.estimates.map(row=>`<button type="button" class="annual-month-result" data-select-month="${row.month}" data-open-month><span>${monthLabel(row.month,true)}</span><strong>${row.value===null?'Income or conversion needed':(row.confirmed?'':'≈ ')+nativeMoney(row.value,'CLP')}</strong></button>`).join('')}</details><div class="hero-bottom"><p>Each month keeps its own income split. ${partial?'This subtotal is incomplete. ':''}Opening balances and unrecorded repayments are separate; no activity is assumed for missing months.</p><button class="button" data-view="monthend">Open Month ${icon('arrow')}</button></div></div>`;
}
function liveMonthEnd(){
  const w=workingMonth(ui.month);
  return `${pageHead('Who owes whom this month',`${monthLabel(ui.month)} · your household’s monthly shared-spending balance.`)}
    <div class="monthend-layout">${practicalSettlementHero(true)}<section class="card card-pad"><div class="card-header"><div><h2 class="section-title">The monthly calculation</h2><p>Income determines the proportional split</p></div><span class="pill neutral">CLP</span></div>
    <div class="income-split-grid">${['neal','partner'].map(p=>`<div class="income-split-tile"><span class="person-badge ${p==='partner'?'partner':''}">${esc(personName(p))}</span><span class="average-label">Income used for the split</span>${w.incomes[p]===null?`<button class="button small" data-month-income="${p}">Enter monthly income</button>`:amountChip(nativeMoney(w.incomes[p],'CLP'))}</div>`).join('')}</div>
    <div class="explain-row"><span>Shared expenses recorded</span>${amountChip(nativeMoney(w.shared,'CLP'))}</div><div class="explain-row"><span>Shared expenses Neal paid</span>${amountChip(nativeMoney(w.paid,'CLP'))}</div>
    <details class="record-notes subsection"><summary>${icon('info')}<span>Calculation notes</span></summary><div><p>This working estimate uses your approved household rule. Unallocated purchases and unidentified transfers are excluded. Freelance income uses invoice month provisionally. Estimated currency conversions are included. This is a provisional calculation, not a confirmed amount due.</p></div></details></section></div>
    <section class="card card-pad subsection month-history-card"><div class="card-header"><div><h2 class="section-title">Earlier months</h2><p>Estimates from classified shared expenses</p></div></div><div class="table-scroll"><table class="compact-table"><thead><tr><th>Month</th><th class="right">Monthly estimate · CLP</th></tr></thead><tbody>${allMonths().filter(m=>m<ui.month).reverse().map(m=>{const x=workingMonth(m);return `<tr class="month-history-row" data-select-month="${m}" tabindex="0"><td>${monthLabel(m)}</td><td class="right">${x.estimate===null?'<span class="muted">Income not supplied</span>':amountChip('≈ '+nativeMoney(x.estimate,'CLP'),true)}</td></tr>`}).join('')}</tbody></table></div><p class="table-note">Positive means Neal would pay Paola; negative means Paola would pay Neal. These monthly estimates do not establish the cumulative unpaid balance. An opening balance and repayments are needed for that.</p></section>`;
}
function monthlyIncomeModal(person){
 if(!['neal','partner'].includes(person))return;
 const currency=person==='partner'?'CLP':'USD';
 openModal(`${personName(person)}’s income · ${monthLabel(ui.month)}`,`<p>Enter the total for this month. This saves an editable monthly income record to your workbook.</p>${field('Monthly income ('+currency+')','income_total','','number','required min="0" step="0.01"')}`,`<button type="submit" class="button primary">Save monthly income</button>`,async form=>{
  const amount=n(Object.fromEntries(form).income_total);if(amount<=0)throw new Error('Enter a positive amount. Zero-income confirmation is a separate setting.');
  if(liveRows(ui.month,'all').some(t=>t.person===person&&t.kind==='income'))throw new Error('Income already exists. Edit the existing transactions to avoid double counting.');
  const incomeCategory=state.categories.find(c=>c.name.toLowerCase()==='income');if(!incomeCategory)throw new Error('Income category is missing.');
  await mutate('/api/transaction',{transaction:{id:'monthly-'+person+'-'+ui.month,date:ui.month+'-01',person,kind:'income',merchant:'Monthly income confirmed by user',category_id:incomeCategory.id,sharing:'personal',amount,currency,charged_amount:amount,charged_currency:currency,fx_clp_per_usd:null,date_basis:'user_confirmed_month',notes:'Monthly total entered in Casa; exact deposit date not specified.',included:true,source_file:'Manual monthly income',review_status:'confirmed'}},'Monthly income saved');
 });
}
